IF OBJECT_ID('tempdb..#LNOrdersForCustomer') IS NOT NULL DROP PROCEDURE #LNOrdersForCustomer;
GO
CREATE PROCEDURE #LNOrdersForCustomer @CustomerId int
AS
BEGIN
 SET NOCOUNT ON;
 SELECT OrderId,Amount FROM #LNOrders WHERE CustomerId=@CustomerId ORDER BY OrderId;
END;
GO
EXEC #LNOrdersForCustomer @CustomerId=2;

