IF @@TRANCOUNT<>0 THROW 51000,'Finish your existing transaction first.',1;
IF OBJECT_ID('tempdb..#LNAtomicWork') IS NOT NULL DROP TABLE #LNAtomicWork;
SELECT OrderId,Amount INTO #LNAtomicWork FROM #LNOrders;
SET XACT_ABORT ON;
BEGIN TRY
 BEGIN TRAN;
 UPDATE #LNAtomicWork SET Amount=999 WHERE OrderId=101;
 THROW 51001,'Simulated failure',1;
 COMMIT;
END TRY
BEGIN CATCH
 IF XACT_STATE()<>0 ROLLBACK;
 SELECT ERROR_MESSAGE() AS DemonstrationError;
END CATCH;
SELECT Amount FROM #LNAtomicWork WHERE OrderId=101; --100

IF OBJECT_ID('tempdb..#LNPlanWork') IS NOT NULL DROP TABLE #LNPlanWork;
