CREATE INDEX IX_LNPlan_CustomerDate ON #LNPlanWork(CustomerId,OrderDate) INCLUDE(Amount);
SET STATISTICS IO ON;
SELECT OrderDate,Amount FROM #LNPlanWork WHERE CustomerId=2 ORDER BY OrderDate;
